def clamp_unit(x: float) -> float | None:
    if x < 0 or not (isinstance(x, float) or isinstance(x, int)):
        return None
    if x <= 1:
        return float(min(max(0, x), 1))
    elif 1 < x <= 10:
        normalized = x / 10
        return float(normalized) if 0 <= normalized <= 1 else None
    elif 10 < x <= 100:
        normalized = x / 100
        return float(normalized) if 0 <= normalized <= 1 else None
    else:
        return None

